// Obtenemos el texto base
let fullText = items[0].json.texto || items[0].json.output || items[0].json.text || "";


// 3. LOGICA DE CORTE (Smart Splitter)
const MAX_LENGTH = 400;
let part1 = "";
let part2 = "";
let needsSplit = false;

if (fullText.length <= MAX_LENGTH) {
    part1 = fullText;
    part2 = "";
    needsSplit = false;
} else {
    // Buscamos la mitad
    const middle = Math.floor(fullText.length / 2);

    // Prioridad de corte: Salto de línea -> Punto -> Espacio -> A la fuerza
    let splitIndex = fullText.lastIndexOf('\n', middle + 200); 
    if (splitIndex === -1 || splitIndex < middle - 200) splitIndex = fullText.lastIndexOf('. ', middle + 200);
    if (splitIndex === -1) splitIndex = fullText.lastIndexOf(' ', middle + 200);
    if (splitIndex === -1) splitIndex = middle;

    part1 = fullText.substring(0, splitIndex + 1).trim();
    part2 = fullText.substring(splitIndex + 1).trim();
    needsSplit = true;


    const countOccurrences = (str, sub) => (str.split(sub).length - 1);


}

return [{
  json: {
    part1: part1,
    part2: part2,
    needs_split: needsSplit
  }
}];

// === Unificar Texto - Identidad Cliente ===

// 1. Atrapamos el super-paquete de datos del nodo anterior
let datosCompletos = {};
try {
  datosCompletos = $('Recuperar datos webhook').first().json;
} catch(e) {
  datosCompletos = $('Resolver Tenant').first().json; // Respaldo
}

// 2. EXTRAEMOS LA IDENTIDAD DE SUPABASE
let nombreVerificado = null;
let esNuevo = true;

try {
  const configTenant = $('Combinar Config Tenant').first().json;
  if (configTenant && configTenant.cliente_id) {
    nombreVerificado = configTenant.cliente_nombre || null;
  }
} catch(e) {}

if (!nombreVerificado) {
  try {
    const upsert = $('Upsert Lead Entrante').first().json;
    const lead = upsert.upsert_lead_entrante || upsert;
    if (lead && lead.id) {
      nombreVerificado = lead.nombre || null;
      esNuevo = (lead.total_visitas === 0 || lead.total_visitas == null);
    }
  } catch(e) {}
}

// 3. EXTRAEMOS EL TEXTO DEL NODO "Texto Final"
let textoUnificado = '[Mensaje vacío]';

try {
  const dataTextoFinal = $('Texto Final').first().json;
  if (dataTextoFinal && dataTextoFinal.input_para_ia) {
    textoUnificado = dataTextoFinal.input_para_ia;
  } else {
    textoUnificado = datosCompletos.message_content || datosCompletos.content || '[Mensaje vacío]';
  }
} catch(e) {
  try {
    const redisData = $input.first().json; 
    const redisContent = redisData ? (redisData.value || redisData.propertyName) : null;
    if (redisContent) {
      const mensajes = JSON.parse(redisContent);
      textoUnificado = Array.isArray(mensajes) ? mensajes.join('\n') : redisContent;
    }
  } catch(errRedis) {}
}

// 4. Creamos la llave maestra (Chat ID)
const telefonoLimpio = datosCompletos.sender_phone ? String(datosCompletos.sender_phone).replace(/\D/g, '') : 'sin_numero';
const chatId = `${datosCompletos.business_id}:${telefonoLimpio}`;

// 5. Se lo mandamos a la IA
return [{
  json: {
    ...datosCompletos,
    input_final: textoUnificado,
    chat_id: chatId,
    nombre_cliente: nombreVerificado,
    nombre_whatsapp: datosCompletos.sender_name,
    es_cliente_nuevo: esNuevo
  }
}];

// =============================================
// RECUPERAR DATOS WEBHOOK - Multi-Tenant Completo
// Consolida: Tenant + Mensaje + Estado del Cliente en Supabase
// =============================================

// 1. RECUPERAR DATOS DEL NEGOCIO (Apuntamos directamente al nodo anterior correcto)
let tenantConfig = {};
try {
  // Intentamos leer exactamente tu nodo llamado 'Resolver Tenant'
  const tenantItems = $('Resolver Tenant').all();
  if (tenantItems && tenantItems.length > 0) {
    tenantConfig = tenantItems[0].json;
  }
} catch (e) {
  // Si le cambiaste el nombre, intentamos con mayúsculas u otros nombres que usabas
  try { tenantConfig = $('RESOLVER TENANT').first().json; } 
  catch(e2) { tenantConfig = $('Combinar Config Tenant').first().json; }
}

// 2. RECUPERAR ESTADO DEL CLIENTE (El nodo inmediatamente anterior, de Supabase)
let cliente = $input.first().json || {};
try {
  const clienteItems = $('Buscar cliente inicial').all();
  if (clienteItems && clienteItems.length > 0) {
    cliente = clienteItems[0].json;
  }
} catch (e) {
  // Ya lo atrapó en la línea de arriba
}

// 3. LÓGICA DE ESTADO (Bot On/Off)
const botGeneralActivo = tenantConfig.canal_activo !== false; 
const botClienteActivo = cliente.bot_activo !== false; 

// 4. SALIDA FINAL HACIA EL RESTO DEL FLUJO
return {
  json: {
    bot_active: botGeneralActivo && botClienteActivo, 

    // === DATOS DEL MENSAJE ===
    message_content: tenantConfig.content,
    message_id: tenantConfig.message_id,
    contact_id: cliente.id || null, 
    sender_name: tenantConfig.sender_name,
    sender_phone: (tenantConfig.sender_phone || '').replace(/\D/g, ''), 
    attachments: tenantConfig.attachments || [],
    canal: tenantConfig.canal || 'whatsapp',

    // === DATOS DEL TENANT (Salón) - CORE ===
    business_id: tenantConfig.business_id,
    instance_name: tenantConfig.instance_name, 
    nombre_negocio: tenantConfig.nombre_negocio,
    nombre_bot: tenantConfig.nombre_bot,
    ubicacion: tenantConfig.ubicacion,
    pais: tenantConfig.pais,
    timezone: tenantConfig.timezone,
    moneda: tenantConfig.moneda,

    // === IDENTIDAD Y ADN COMPLETO (Pasa intacto) ===
    marca_identidad: tenantConfig.marca_identidad,
    recursos_saas: tenantConfig.recursos_saas || {}, // <-- AQUÍ ESTÁ LA LÍNEA QUE FALTABA

    // === HORARIOS Y AGENDAMIENTO ===
    hora_apertura: tenantConfig.hora_apertura,
    hora_cierre: tenantConfig.hora_cierre,
    dias_trabajo: tenantConfig.dias_trabajo,
    calendarios: tenantConfig.calendarios,

    // === REGLAS Y VENTAS ===
    faq: tenantConfig.faq,
    politicas_reserva: tenantConfig.politicas_reserva,
    metodos_pago: tenantConfig.metodos_pago,
    promociones: tenantConfig.promociones,

    // === HUMANO DE RESPALDO ===
    nombre_recepcionista: tenantConfig.nombre_recepcionista,
    telefono_recepcionista: tenantConfig.telefono_recepcionista,

    // === ESTADO DE ATENCIÓN HUMANA ===
    bot_cliente_pausado: !botClienteActivo, 
    bot_pausado_hasta: cliente.bot_pausado_hasta || null,
    bot_pausado_razon: cliente.bot_pausado_razon || null
  }
};

const output = $input.first().json.output || $('Guardia de Respuesta').first().json.output || "";
const guardia = $input.first().json._guardia || {};
const paso = $input.first().json._paso || "ok";

// Detectar URLs de imagen
const imagenRegex = /(https?:\/\/[^\s]+\.(jpg|jpeg|png|webp|gif))/gi;
// Detectar URLs de video (mp4, mov, Google Drive)
const videoRegex = /(https?:\/\/[^\s]+\.(mp4|mov|avi|webm))|(https?:\/\/drive\.google\.com\/[^\s]+)/gi;

const imagenes = (output || "").match(imagenRegex) || [];
const videos = (output || "").match(videoRegex) || [];

// Limpiar texto (quitar todas las URLs de media)
let textoLimpio = output || "";
imagenes.forEach(url => textoLimpio = textoLimpio.replace(url, ''));
videos.forEach(url => textoLimpio = textoLimpio.replace(url, ''));
textoLimpio = textoLimpio.replace(/\n{3,}/g, '\n\n').trim();

// Determinar tipo de media
let tipoMedia = 'ninguno';
let mediaUrl = null;

if (videos.length > 0) {
  tipoMedia = 'video';
  mediaUrl = videos[0];
} else if (imagenes.length > 0) {
  tipoMedia = 'image';
  mediaUrl = imagenes[0];
}

return {
  json: {
    tieneMedia: tipoMedia !== 'ninguno',
    tipoMedia: tipoMedia,  // 'image', 'video', o 'ninguno'
    mediaUrl: mediaUrl,
    texto: textoLimpio,
    _guardia: guardia,
    _paso: paso
  }
};

const body = $input.first().json.body;

// 1. CHEQUEO DE SKIP (Ignorar si no es un mensaje entrante o saliente relevante)
const isMessageUpsert = body.event === 'messages.upsert';

if (!isMessageUpsert || !body.data) {
  return {
    json: {
      skip: true,
      motivo: 'No es un evento de mensaje nuevo',
      instance_name: body.instance || 'desconocida'
    }
  };
}

const data = body.data;
const isFromMe = data.key?.fromMe === true; // true si lo envió el negocio/recepcionista

const instanceName = body.instance; 
const remoteJid = data.key.remoteJid || '';

// ============================================================
// NORMALIZACIÓN DE IDENTIFICADOR DE REMITENTE
// Maneja todos los formatos conocidos y futuros de WhatsApp:
//   - @s.whatsapp.net  → número de teléfono normal
//   - @g.us            → grupo (no se procesa como cliente)
//   - @lid             → Link ID (privacidad de número)
//   - @newsletter      → canales/newsletters (futuro)
//   - @username.net    → usernames (nuevo en 2025-2026)
// ============================================================

const isGroup = remoteJid.endsWith('@g.us');
const isLid = remoteJid.endsWith('@lid');
const isNewsletter = remoteJid.endsWith('@newsletter');
const isUsername = remoteJid.includes('@username') || remoteJid.startsWith('~');

const rawId = remoteJid.split('@')[0];
const isNumericPhone = /^\d{7,15}$/.test(rawId);

let senderPhone;
let senderIdType;

if (isGroup) {
  senderPhone = rawId;
  senderIdType = 'group';
} else if (isLid) {
  senderPhone = remoteJid;
  senderIdType = 'lid';
} else if (isNewsletter || isUsername) {
  senderPhone = remoteJid;
  senderIdType = 'username';
} else if (isNumericPhone) {
  senderPhone = rawId;
  senderIdType = 'phone';
} else {
  senderPhone = rawId.replace('@s.whatsapp.net', '');
  senderIdType = 'unknown';
}

const senderName = isFromMe ? 'Recepcionista' : (data.pushName || 'Cliente');

// 3. EXTRAER CONTENIDO
let content = '';
let hasMedia = false;
let mediaType = data.messageType || 'conversation'; 
let tipoArchivo = 'texto';

if (data.message) {
  if (data.message.conversation) {
    content = data.message.conversation; 
  } else if (data.message.extendedTextMessage && data.message.extendedTextMessage.text) {
    content = data.message.extendedTextMessage.text; 
  } else if (data.message.imageMessage) {
    content = data.message.imageMessage.caption || '';
    hasMedia = true;
    tipoArchivo = 'imagen';
  } else if (data.message.audioMessage) {
    content = '';
    hasMedia = true;
    tipoArchivo = 'audio';
  } else if (data.message.videoMessage) {
    content = data.message.videoMessage.caption || '';
    hasMedia = true;
    tipoArchivo = 'video';
  } else if (data.message.documentMessage) {
    content = data.message.documentMessage.fileName || 'Documento adjunto';
    hasMedia = true;
    tipoArchivo = 'documento';
  }
}

// 4. ESTRUCTURA UNIFICADA PARA EL RESTO DEL FLUJO
return {
  json: {
    skip: false,
    es_saliente: isFromMe,
    canal: 'whatsapp',
    instance_name: instanceName,   
    sender_id: remoteJid,          
    sender_phone: senderPhone,
    sender_id_type: senderIdType,
    sender_name: senderName,
    content: content,
    has_media: hasMedia,
    media_type_raw: mediaType,      
    tipo_archivo: tipoArchivo,      
    message_id: data.key.id,
    created_at: body.date_time,
    _raw_body: body                
  }
};

// =============================================
// RESOLVER TENANT - Extraer Contexto del Negocio y Cliente
// =============================================

const norm = $('Normalizar Entrada').first().json;
let negocio = null;

try {
  const negocioItems = $('Buscar Negocio').all(); 
  if (negocioItems && negocioItems.length > 0) {
    negocio = negocioItems[0].json;
  }
} catch (error) {
  negocio = null;
}

if (!negocio || !negocio.id) {
  return { json: { skip: true, motivo: 'Salón no encontrado en BD para la instancia: ' + norm.instance_name } };
}

const parseJSON = (str) => {
  if (!str) return {};
  try { return typeof str === 'string' ? JSON.parse(str) : str; } 
  catch (e) { return {}; }
};

const botConfig = parseJSON(negocio.bot_config);
const marcaIdentidadCompleta = parseJSON(negocio.marca_identidad); // AQUI TRAEMOS TODO EL JSON
const calendarios = parseJSON(negocio.calendarios);
const promociones = parseJSON(negocio.promociones);
const diasTrabajo = parseJSON(negocio.dias_trabajo);

const telRecepcionista = negocio.telefono_recepcionista ? String(negocio.telefono_recepcionista).replace('.0', '') : '';

return {
  json: {
    // 1. DATOS DEL MENSAJE
    canal: norm.canal,
    instance_name: norm.instance_name,
    sender_id: norm.sender_id,
    sender_phone: norm.sender_phone,
    sender_name: norm.sender_name,
    content: norm.content,
    has_media: norm.has_media,
    media_type: norm.media_type,
    message_id: norm.message_id,
    created_at: norm.created_at,
    _raw_body: norm._raw_body,

    // 2. DATOS DEL SALÓN
    business_id: negocio.id,
    nombre_negocio: negocio.nombre,
    ubicacion: negocio.ubicacion,
    pais: negocio.pais,
    moneda: negocio.moneda,

    // 3. IDENTIDAD Y PERSONALIDAD DEL BOT
    canal_activo: negocio.activo !== false,
    nombre_bot: botConfig.nombre || marcaIdentidadCompleta?.adn_json?.nombre_bot || 'Luna',

    // LA SOLUCION: PASAMOS EL JSON COMPLETO INTACTO HACIA ADELANTE
    marca_identidad: marcaIdentidadCompleta, 

    // 4. HORARIOS Y AGENDAMIENTO
    timezone: negocio.timezone || 'America/Lima',
    hora_apertura: negocio.hora_apertura,
    hora_cierre: negocio.hora_cierre,
    dias_trabajo: diasTrabajo,
    calendarios: calendarios,

    // 5. REGLAS, FAQ Y VENTAS
    faq: negocio.faq,
    politicas_reserva: negocio.politicas_reserva,
    metodos_pago: negocio.metodos_pago,
    promociones: promociones,

    // 6. HUMANO DE RESPALDO
    nombre_recepcionista: negocio.nombre_recepcionista || 'nuestro equipo',
    telefono_recepcionista: telRecepcionista
  }
};

// === Combinar Config Tenant ===
// Fusiona datos del webhook normalizado + datos del negocio desde Supabase
// + estado del bot por cliente (bot_pausado) y captura del ID de cliente

const canal = $('Resolver Tenant').first().json;
const negocio = $('Buscar Negocio').first().json;

// 1. CAPTURAR DATOS DEL CLIENTE (Desde Upsert Lead Entrante)
let clienteData = null;

try {
  const upsertItem = $('Upsert Lead Entrante').first().json;
  clienteData = upsertItem.upsert_lead_entrante || upsertItem;
} catch(e) {
  try {
    const itemsBuscar = $('Buscar Bot Cliente').all();
    if (itemsBuscar && itemsBuscar.length > 0 && itemsBuscar[0].json && itemsBuscar[0].json.id) {
      clienteData = itemsBuscar[0].json;
    }
  } catch(e2) {}
}

// 2. EXTRAER ID Y VARIABLES DEL BOT
let clienteId = null;
let botPausadoCliente = false;
let botPausadoHasta = null;
let botPausadoRazon = null;

if (clienteData && clienteData.id) {
  clienteId = clienteData.id;
  botPausadoCliente = clienteData.bot_pausado === true;
  botPausadoHasta = clienteData.bot_pausado_hasta || null;
  botPausadoRazon = clienteData.bot_pausado_razon || null;

  // Si la fecha ya paso, tratamos como activo
  if (botPausadoCliente && botPausadoHasta) {
    const ahora = new Date();
    const hasta = new Date(botPausadoHasta);
    if (hasta <= ahora) {
      botPausadoCliente = false;
      botPausadoHasta = null;
      botPausadoRazon = null;
    }
  }
}

// Extraer recursos_saas (Feature Flags SaaS)
const recursosSaaS = negocio.recursos_saas || {
  plan_base: 'automatico',
  chatbot: { tipo: 'autonomo', activo: true },
  modulos: {},
  limites: { max_staff: 3 }
};

return [{
  json: {
    ...canal,
    business_id: negocio.id,
    nombre_bot: negocio.marca_identidad?.adn_json?.nombre_bot || recursosSaaS.chatbot?.nombre || negocio.bot_config?.nombre || 'Nilah',
    nombre_negocio: negocio.nombre,
    timezone: negocio.timezone || 'America/Lima',
    moneda: negocio.moneda || 'S/.',
    idioma: negocio.idioma || 'es-PE',
    bot_config: negocio.bot_config || {},
    recursos_saas: recursosSaaS,
    chatbot_tipo: recursosSaaS.bot?.modo || 'autonomo',
    chatwoot_api_url: negocio.chatwoot_api_url || 'https://chat.koratflow.agency',
    chatwoot_api_token: negocio.chatwoot_api_token || '',
    chatwoot_account_id: negocio.chatwoot_account_id || canal.account_id,
    telefono_recepcionista: negocio.telefono_recepcionista,
    marca_identidad: negocio.marca_identidad || null,

    // --- ID y Estado del bot por cliente ---
    cliente_id: clienteId,
    cliente_nombre: clienteData?.nombre || canal.sender_name || 'Cliente',
    bot_cliente_pausado: botPausadoCliente,
    bot_pausado_hasta: botPausadoHasta,
    bot_pausado_razon: botPausadoRazon
  }
}];

const output = $json.output || "";
const mockContext = $json._mockContext || null;

const problemas = [];

// ═══════════════════════════════════════════
// 1. RESPUESTA VACÍA
// ═══════════════════════════════════════════
if (output.trim().length === 0) {
  problemas.push("🔴 respuesta_vacia");
}

// ═══════════════════════════════════════════
// 2. RESPUESTA MUY CORTA
// ═══════════════════════════════════════════
if (output.trim().length > 0 && output.trim().length < 7) {
  problemas.push("🟡 respuesta_muy_corta");
}

// ═══════════════════════════════════════════
// 3. FUGA DE INFORMACIÓN TÉCNICA
// ═══════════════════════════════════════════
const patronesTecnicos = [
  /\berror\b/i,
  /exception/i,
  /undefined/i,
  /\bnull\b/i,
  /column.*not.*exist/i,
  /supabase/i,
  /postgresql/i,
  /ECONNREFUSED/i,
  /timeout/i,
  /\b500\b/,
  /\b403\b/,
  /\b404\b/,
  /stack.?trace/i,
  /node_modules/i,
  /ENOTFOUND/i,
  /ETIMEDOUT/i,
  /socket hang up/i,
  /fetch failed/i,
  /network error/i,
  /rate.?limit/i,
  /quota.?exceeded/i,
  /invalid.?api.?key/i,
  /authentication/i,
  /unauthorized/i,
  /CORS/i,
  /JSON\.parse/i,
  /syntax.?error/i,
  /cannot read propert/i,
  /is not defined/i,
  /is not a function/i,
  /unexpected token/i
];

for (const patron of patronesTecnicos) {
  if (patron.test(output)) {
    problemas.push("🔴 fuga_tecnica");
    break;
  }
}

// ═══════════════════════════════════════════
// 3.1. FUGA DE INSTRUCCIONES / INNER MONOLOGUE
// ═══════════════════════════════════════════
const patronesPrompt = [
  /system.?prompt/i,
  /instructions/i,
  /according to persona/i,
  /must not mention/i,
  /user corrected name/i,
  /let's craft/i,
  /provide single message/i,
  /assistant had previously/i,
  /one message, warm/i,
  /use emojis/i,
  /closure question/i,
  /execution/i,
  /\bpersona\b/i,
  /we need to/i,       // Corregido: ahora es Regex
  /according to/i,     // Corregido
  /here assistant/i,   // Corregido
  /let's craft/i,      // Corregido
  /send final/i,       // Corregido
  /also must/i,        // Corregido
  /okay\./i            // Corregido (escapamos el punto)
];

for (const patron of patronesPrompt) {
  if (patron.test(output)) {
    problemas.push("🔴 fuga_instrucciones_sistema");
    break;
  }
}

// ═══════════════════════════════════════════
// 4. IDIOMA INCORRECTO
// ═══════════════════════════════════════════
const tieneEspanol = /[áéíóúñ¿¡]/i.test(output) ||
  /\b(hola|gracias|cita|servicio|salón|belleza|uñas|cabello|corte|color|turno|agenda|precio)\b/i.test(output);

const soloIngles = /\b(sorry|error|failed|unable|cannot|issue|problem|request|apologize)\b/i.test(output) && !tieneEspanol;

if (soloIngles && output.length > 20) {
  problemas.push("🟡 idioma_incorrecto");
}

// ═══════════════════════════════════════════
// 5. RESPUESTA REPETITIVA / LOOP
// ═══════════════════════════════════════════
const palabras = output.toLowerCase().split(/\s+/);
if (palabras.length > 10) {
  const frecuencia = {};
  for (const palabra of palabras) {
    if (palabra.length > 3) {
      frecuencia[palabra] = (frecuencia[palabra] || 0) + 1;
    }
  }
  const maxRepeticion = Math.max(...Object.values(frecuencia));
  if (maxRepeticion > palabras.length * 0.4) {
    problemas.push("🟡 respuesta_repetitiva");
  }
}

// ═══════════════════════════════════════════
// 6. ALUCINACIÓN DE CONTACTO FALSO (LISTA BLANCA + SUPABASE)
// ═══════════════════════════════════════════
const telefonoFalso = /\+?\d{1,3}[\s-]?\(?\d{2,4}\)?[\s-]?\d{3,4}[\s-]?\d{3,4}/.test(output);
const emailFalso = /[\w.-]+@[\w.-]+\.\w{2,}/.test(output);

// LISTA BLANCA: Permite redes sociales, Drive y TU proyecto específico de Supabase.
const urlFalsa = /https?:\/\/(?!(wa\.me|drive\.google\.com|www\.instagram\.com|instagram\.com|fb\.com|facebook\.com|tiktok\.com|www\.tiktok\.com|cfgpgpqbqqeavdbdzwoz\.supabase\.co))[\w.-]+/.test(output);

if (telefonoFalso || emailFalso || urlFalsa) {
  problemas.push("🟡 posible_alucinacion_contacto");
}

// ═══════════════════════════════════════════
// 7. RESPUESTA EXCESIVAMENTE LARGA
// ═══════════════════════════════════════════
if (output.length > 2000) {
  problemas.push("🟡 respuesta_muy_larga");
}

// ═══════════════════════════════════════════
// DECISIÓN
// ═══════════════════════════════════════════
