"${outputUsuario}"

━━━━━━━━━━━━━━━━━━━━`;

return [{ json: { mensaje } }];

// =============================================
// CALCULAR DELAY HUMANO (Anti-Ban) - Optimizado
// =============================================

// Ajusta esta ruta según donde guardes el texto de la IA
// Si viene del nodo "Message a model", usa la ruta que extrajimos antes
const textoIA = $input.item.json.output || ""; 
const longitud = textoIA.length;

// Verifica si el mensaje entrante era audio (opcional)
const esAudio = $input.item.json.has_media && String($input.item.json.media_type).includes("audio");

// Configuración Base
const BASE_DELAY = 1500; // 1.5 seg mínimo de "reacción"
const MS_POR_CARACTER = 60; // Un humano promedio escribe a 40-70ms por tecla
const MAX_DELAY = 10000; // No más de 10 seg para no perder al cliente

// Cálculo base
let delayCalculado = BASE_DELAY + (longitud * MS_POR_CARACTER);

if (esAudio) {
  delayCalculado += 3000; // Simular que "graba" toma más tiempo
}

// Jitter (variación aleatoria ±15%) para que nunca sea igual
const variacion = delayCalculado * 0.15;
const jitter = Math.floor(Math.random() * (variacion * 2)) - variacion;
let delayFinal = Math.floor(delayCalculado + jitter);

// Aplicar límites
if (delayFinal > MAX_DELAY) delayFinal = MAX_DELAY;
if (delayFinal < 1500) delayFinal = 1500;

return {
    // Mantenemos los datos anteriores y añadimos los cálculos
    ...$input.item.json,
    delay_ms: delayFinal,
    delay_seconds: Math.ceil(delayFinal / 1000),
    _debug_longitud: longitud
};

